#!/usr/bin/env python3
import pathlib,hashlib,json,difflib
root=pathlib.Path('/home/qian-qi/work/chain-w1-c8-root-tools-20261108-ec265b')
records=[]
def derive(source,result,replacements):
 b=(root/source).read_bytes();s=b.decode()
 for before,after in replacements:
  assert s.count(before)==1,(source,before,s.count(before));s=s.replace(before,after)
 compile(s,str(root/result),'exec')
 with (root/result).open('x') as w:w.write(s)
 with (root/(result+'.diff')).open('x') as w:w.write(''.join(difflib.unified_diff(b.decode().splitlines(True),s.splitlines(True),fromfile=source,tofile=result)))
 records.append({'source':source,'source_sha256':hashlib.sha256(b).hexdigest(),'result':result,'result_sha256':hashlib.sha256(s.encode()).hexdigest()})
assert hashlib.sha256((root/'publish_c8_source.py').read_bytes()).hexdigest()=='f8e64fe76dc1602cf8703aa78b096810d0bc5c74a0219b6dfbf6bae8d44a696b'
